// AWP 真实模型（来源 J:////武器////awp////7cbf8dad723a866b3b3db03fb68da544.obj，fast_simplification 减面 95%）
// 原始: 749,948 顶点 / 1,499,964 面 → 减面后: 37,465 顶点 / 74,998 面
// 原始坐标系: X=枪长(1.19, +X 端为枪口), Y=高度(0.32), Z=宽度(0.21)
// 已减去包围盒中心 (cx=0.1119, cy=0.1617, cz=-0.0001) → 当前坐标中心 (0,0,0)
// viewmodel 映射: rotation.y=+PI/2 使 +X(枪口)→-Z(前方), -X(枪托)→+Z(后方)
window.AwpModel = (function () {
  const POS_B64 = '';
  const UV_B64  = '';
  const IDX_B64 = '';
  const POS_CNT = 37465;
  const UV_CNT  = 37465;
  const IDX_CNT = 224994;
  const IDX_FMT = 'H';

  function b64ToBuf(b64) {
    const bin = atob(b64);
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    return arr.buffer;
  }

  function build(geometry, material) {
    const posArr = new Float32Array(b64ToBuf(POS_B64));
    const uvArr  = new Float32Array(b64ToBuf(UV_B64));
    const idxArr = IDX_FMT === 'H' ? new Uint16Array(b64ToBuf(IDX_B64)) : new Uint32Array(b64ToBuf(IDX_B64));

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(posArr, 3));
    geo.setAttribute('uv', new THREE.BufferAttribute(uvArr, 2));
    geo.setIndex(new THREE.BufferAttribute(idxArr, 1));
    geo.setAttribute('uv2', new THREE.BufferAttribute(uvArr.slice(), 2));
    geo.computeVertexNormals();
    geo.computeBoundingSphere();

    const mesh = new THREE.Mesh(geo, material);
    mesh.rotation.y = Math.PI / 2;
    return mesh;
  }

  return { build, posCount: POS_CNT, idxCount: IDX_CNT, idFormat: IDX_FMT };
})();
